The overload is in place. My test constructs a Moq `Mock<IHttpClientWrapper>`, calls the injected overload `FetchAsync(url, wrapper.Object)`, and verifies the HTTP call went through the seam.

<tool>submit_test(csharp)</tool>
```csharp
using Moq;
using Xunit;
using System.Net.Http;
using System.Threading.Tasks;

namespace Acme.Tests;

public class ApiClientSeamTests
{
    [Fact]
    public async Task FetchAsync_UsesInjectedWrapper()
    {
        var client = new ApiClient(new HttpClient());
        var wrapper = new Mock<IHttpClientWrapper>();
        wrapper.Setup(w => w.GetAsync(It.IsAny<string>()))
               .ReturnsAsync(new HttpResponseMessage());
        var body = await client.FetchAsync("http://x", wrapper.Object);
        wrapper.Verify(w => w.GetAsync("http://x"), Times.Once);
    }
}
